            if self.seen.longhands.contains(longhand_id) {
                // Found it!
                self.did_apply_prioritary_property(context, id);
                return;
            }
            debug_assert!(
                decl.next_index == 0 || decl.next_index > index,
                "should make progress! {} -> {}",
                index,
                decl.next_index,
            );
            index = decl.next_index;
            if index == 0 {
                return;
            }
        }
    }

